import{_ as a,c as t,o,ag as i}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"Community Recommended Episodes","description":"","frontmatter":{"title":"Community Recommended Episodes"},"headers":[],"relativePath":"community/community-recommended-episodes.md","filePath":"community/community-recommended-episodes.md","lastUpdated":null}'),r={name:"community/community-recommended-episodes.md"};function n(s,e,c,l,d,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="community-recommended-episodes" tabindex="-1">Community Recommended Episodes <a class="header-anchor" href="#community-recommended-episodes" aria-label="Permalink to &quot;Community Recommended Episodes&quot;">​</a></h1><h2 id="recommended-episodes" tabindex="-1">Recommended Episodes <a class="header-anchor" href="#recommended-episodes" aria-label="Permalink to &quot;Recommended Episodes&quot;">​</a></h2><p>Recommended Episodes are direct episodes, not entire podcasts or channels. Please include the following: - Direct link to the episode, not just the Apple podcast or other podcast listening link. - A brief description of why this episode is recommended - Any description or notes from the episode?</p><h3 id="beginner" tabindex="-1">Beginner <a class="header-anchor" href="#beginner" aria-label="Permalink to &quot;Beginner&quot;">​</a></h3><h3 id="privacy-security" tabindex="-1">Privacy/Security <a class="header-anchor" href="#privacy-security" aria-label="Permalink to &quot;Privacy/Security&quot;">​</a></h3><p>Malicious Life Podcast: Inside NotPetya, Part 1 (Tim) - <a href="https://www.cybereason.com/blog/malicious-life-podcast-inside-notpetya-ransomware-part-1" target="_blank" rel="noreferrer">https://www.cybereason.com/blog/malicious-life-podcast-inside-notpetya-ransomware-part-1</a> - Malicious life is made by cyber reason, which is an Israeli company of format 8200 members…its good shit. You will have to skip episodes, tho, as every ten or so are just 30-minute commercials. &gt; On June 28th, 2017, millions of Ukrainians celebrated Constitution Day. Their national holiday turned into a nightmare, as tens of thousands of computers all over the country were infected by mysterious malware. By that afternoon, the cyber pandemic was already going global. In this episode, Host Ran Levi is joined by Amit Serper, Area VP of Security Research for North America at Guardicore. He was the first researcher to tackle NotPetya and provide a solution when he was the Principal Security Researcher at Cybereason.</p><h3 id="unmanned-systems" tabindex="-1">Unmanned Systems <a class="header-anchor" href="#unmanned-systems" aria-label="Permalink to &quot;Unmanned Systems&quot;">​</a></h3><ul><li>It’s a good podcast on Iranian UAS proliferation with Tovo and some smart political scientists. Claims that forward deploying robots can increase harassment by adversaries because our adversaries perceive that we will limit our responses to strikes against robots to nonkinetic means. I suggest this happened with TF-59, which I’m unsure about. But the idea is interesting. <a href="https://mwi.westpoint.edu/social-science-of-war-drone-proliferation-to-terrorists-proxies/" target="_blank" rel="noreferrer">https://mwi.westpoint.edu/social-science-of-war-drone-proliferation-to-terrorists-proxies/</a></li></ul><h3 id="self-hosting" tabindex="-1">Self Hosting <a class="header-anchor" href="#self-hosting" aria-label="Permalink to &quot;Self Hosting&quot;">​</a></h3><p>The Privacy, Security, and OSINT Show: Episodes <a href="https://feeds.soundcloud.com/stream/1541980267-user-98066669-300-self-hosted-2-offline-knowledge.mp3" target="_blank" rel="noreferrer">300</a> &amp; <a href="https://feeds.soundcloud.com/stream/1547994979-user-98066669-301-self-hosted-3-calendars-contacts-notes.mp3" target="_blank" rel="noreferrer">301</a> (Sac) - <a href="https://inteltechniques.com/podcast.html" target="_blank" rel="noreferrer">https://inteltechniques.com/podcast.html</a> - Michael Bazzell, known for the OSINT Techniques and Extreme Privacy books, has a series of episodes covering self-hosting from the absolute most beginner level of using your computer to more advanced self-hosting of password managers, email, email masking, and more. These two episodes are some of the more basic ones, but they are things you can start doing today! ### Research/“OSINT” Bellingcat Podcast: MH17, Episode 4 Guide: Manhunt (Tim) - <a href="https://www.bellingcat.com/resources/podcasts/2019/08/07/bellingcat-podcast-mh17-episode-4-guide-manhunt/" target="_blank" rel="noreferrer">https://www.bellingcat.com/resources/podcasts/2019/08/07/bellingcat-podcast-mh17-episode-4-guide-manhunt/</a> - This podcast is about the shooting down of MH17. This episode is crazy good because of the voice calls they found. For those of you in the tech space, OSINT is often overlooked but plays an important part in what we all do. &gt; A set of secretly recorded phone calls contain the voices and code names of some of the shadowy figures believed to be responsible for shooting down Flight MH17. Bellingcat launches a manhunt. ### Artificial Intelligence (AI) / Machine Learning (ML)</p><p>#183 Julie Janson on Air Force IO Talent and Strategy,” February 13, 2024, in the Cognitive Crucible, hosted by John Bicknell, podcast, MP3 audio, 44:43, <a href="https://information-professionals.org/episode/cognitive-crucible-episode-183/" target="_blank" rel="noreferrer">https://information-professionals.org/episode/cognitive-crucible-episode-183/</a>. ### Strategic Focus ### Project Management / Leadership ### Programing / Development ## Hobbyist ### Privacy/Security ### Self Hosting ### Research/“OSINT” ### Artificial Intelligence (AI) / Machine Learning (ML) ### Strategic Focus ### Project Management / Leadership ### Programing / Development</p><h3 id="expert" tabindex="-1">Expert <a class="header-anchor" href="#expert" aria-label="Permalink to &quot;Expert&quot;">​</a></h3><h3 id="privacy-security-1" tabindex="-1">Privacy/Security <a class="header-anchor" href="#privacy-security-1" aria-label="Permalink to &quot;Privacy/Security&quot;">​</a></h3><h3 id="self-hosting-1" tabindex="-1">Self Hosting <a class="header-anchor" href="#self-hosting-1" aria-label="Permalink to &quot;Self Hosting&quot;">​</a></h3><h3 id="research-osint" tabindex="-1">Research/“OSINT” <a class="header-anchor" href="#research-osint" aria-label="Permalink to &quot;Research/“OSINT”&quot;">​</a></h3><h3 id="artificial-intelligence-ai-machine-learning-ml" tabindex="-1">Artificial Intelligence (AI) / Machine Learning (ML) <a class="header-anchor" href="#artificial-intelligence-ai-machine-learning-ml" aria-label="Permalink to &quot;Artificial Intelligence (AI) / Machine Learning (ML)&quot;">​</a></h3><h3 id="strategic-focus" tabindex="-1">Strategic Focus <a class="header-anchor" href="#strategic-focus" aria-label="Permalink to &quot;Strategic Focus&quot;">​</a></h3><h3 id="project-management-leadership" tabindex="-1">Project Management / Leadership <a class="header-anchor" href="#project-management-leadership" aria-label="Permalink to &quot;Project Management / Leadership&quot;">​</a></h3><h3 id="programing-development" tabindex="-1">Programing / Development <a class="header-anchor" href="#programing-development" aria-label="Permalink to &quot;Programing / Development&quot;">​</a></h3>',19)])])}const u=a(r,[["render",n]]);export{p as __pageData,u as default};
